describe('correlation (research table)', () => {
  it('DDHQ: joint 52 % exceeds the independence product of 40.5 %', () => {
    const { house, senate, sweep } = RESEARCH.ddhq;
    expect(independentSweep(house, senate)).toBeCloseTo(0.405, 4);
    expect(sweep).toBeGreaterThan(independentSweep(house, senate));
    expect(correlationLift(sweep, house, senate)).toBeCloseTo(1.284, 3);
    expect(impliedPhi(sweep, house, senate)).toBeGreaterThan(0.5);
  });

  it('every source with a joint value implies positive correlation', () => {
    for (const s of RESEARCH_SOURCES) {
      if (s.sweep === null || s.house === null || s.senate === null) continue;
      expect(correlationLift(s.sweep, s.house, s.senate), s.name).toBeGreaterThan(1);
    }
  });

  it('every joint value lies within its Fréchet bounds', () => {
    for (const s of RESEARCH_SOURCES) {
      if (s.sweep === null || s.house === null || s.senate === null) continue;
      const b = frechetBounds(s.house, s.senate);
      expect(s.sweep, s.name).toBeGreaterThanOrEqual(b.lo);
      expect(s.sweep, s.name).toBeLessThanOrEqual(b.hi);
    }
  });

  it('Silver Bulletin derived sweep (~68 %) is consistent with its 91 % / 69 % marginals', () => {
    const b = frechetBounds(RESEARCH.silver.house, RESEARCH.silver.senate);
    expect(b.lo).toBeCloseTo(0.6, 6);
    expect(b.hi).toBe(0.69);
    expect(RESEARCH.silver.derivedSweep).toBeGreaterThanOrEqual(b.lo);
    expect(RESEARCH.silver.derivedSweep).toBeLessThanOrEqual(b.hi);
  });

  it('P(sweep) ≈ P(Senate): the Senate is the binding constraint (gap ≤ 2 pts)', () => {
    for (const s of RESEARCH_SOURCES) {
      if (s.sweep === null || s.senate === null) continue;
      expect(s.senate - s.sweep, s.name).toBeGreaterThanOrEqual(0);
      expect(s.senate - s.sweep, s.name).toBeLessThanOrEqual(0.02 + 1e-9);
    }
  });

  it('D Senate + R House is near-impossible (Polymarket 1 %, DDHQ 2 %)', () => {
    expect(RESEARCH.polymarket.balanceOfPower.DS_RH).toBeLessThanOrEqual(0.01);
    expect(RESEARCH.ddhq.combos.DS_RH).toBeLessThanOrEqual(0.02);
  });

  it('balance-of-power outcomes form a coherent distribution', () => {
    const sum = (o: Record<string, number>) => Object.values(o).reduce((a, b) => a + b, 0);
    expect(sum(RESEARCH.ddhq.combos)).toBeCloseTo(1, 6);
    // Market prices include a small overround.
    expect(sum(RESEARCH.polymarket.balanceOfPower)).toBeGreaterThanOrEqual(0.97);
    expect(sum(RESEARCH.polymarket.balanceOfPower)).toBeLessThanOrEqual(1.05);
    // DDHQ: P(D Senate) = DD + DS_RH
    expect(RESEARCH.ddhq.combos.DD + RESEARCH.ddhq.combos.DS_RH).toBeCloseTo(RESEARCH.ddhq.senate, 6);
    expect(RESEARCH.ddhq.combos.DD + RESEARCH.ddhq.combos.RS_DH).toBeCloseTo(RESEARCH.ddhq.house, 6);
  });
});

describe('Senate bottleneck (research key races)', () => {
  it('Democrats need 8 of the 13 tracked races (net +4 for 51 seats)', () => {
    expect(senateOutlook(RESEARCH_RACES).needed).toBe(8);
    expect(RESEARCH_RACES).toHaveLength(13);
  });

  it('baseline plus tracked races account for all 100 seats', () => {
    expect(SENATE_BASELINE.dem + SENATE_BASELINE.rep + RACES.length).toBe(100);
  });

  it('favorites deliver 52 seats', () => {
    expect(senateOutlook(RESEARCH_RACES).favoriteSeats).toBe(52);
  });

  it('the 51st seat runs through Ohio', () => {
    expect(senateOutlook(RESEARCH_RACES).tippingPoint).toBe('OH');
  });

  it('Iowa is the only toss-up with Democrats trailing; KS, SC, FL are long shots', () => {
    const trailing = RESEARCH_RACES.filter((r) => raceProbability(r)! < 0.5).map((r) => r.state);
    expect(trailing).toEqual(['IA', 'KS', 'SC', 'FL']);
    expect(RESEARCH_RACES.filter((r) => raceProbability(r)! >= 0.4 && raceProbability(r)! < 0.5).map((r) => r.state)).toEqual(['IA']);
  });

  it('losing Michigan leaves zero margin; losing Michigan and Maine loses the majority', () => {
    expect(senateOutlook(RESEARCH_RACES, { MI: 'R' }).favoriteSeats).toBe(51);
    expect(senateOutlook(RESEARCH_RACES, { MI: 'R', ME: 'R' }).favoriteSeats).toBe(50);
  });

  it('independent races imply a Senate majority in the same ballpark as markets/models (54–69 %)', () => {
    const p = senateOutlook(RESEARCH_RACES).pMajorityIndependent;
    expect(p).toBeGreaterThan(RESEARCH.ddhq.senate);
    expect(p).toBeLessThan(RESEARCH.silver.senate);
    expect(senateOutlook(RESEARCH_RACES).expectedSeats).toBeCloseTo(50.85, 2);
  });

  it('forcing picks pins the probability', () => {
    const allD = Object.fromEntries(RESEARCH_RACES.map((r) => [r.state, 'D' as const]));
    const allR = Object.fromEntries(RESEARCH_RACES.map((r) => [r.state, 'R' as const]));
    expect(senateOutlook(RESEARCH_RACES, allD).pMajorityIndependent).toBe(1);
    expect(senateOutlook(RESEARCH_RACES, allR).pMajorityIndependent).toBe(0);
    expect(senateOutlook(RESEARCH_RACES, allD).favoriteSeats).toBe(56);
  });
});

